"use client";
import React, { useEffect, useState } from "react";
import Destinations from "../../after-your-booking/destinations";
import BlogTeasers from "../../after-your-booking/blog-teasers";
import TourCategories from "../tour-categories";

const pledges = [
  {
    title: "Community and Well-being",
    image: "/images/maui.webp",
    href: "/why-travelshop/climate#citizens",
    body: "We empower travelers and partners to create positive change. By using sustainability tools, our adventure network safeguards tourism communities, supports local businesses, and encourages mindful practices.",
  },
  {
    title: "Environmental Impact and Preservation",
    image: "/images/coffee.avif",
    href: "/why-travelshop/climate#earth",
    body: "We inspire our team, travelers, and partners through a culture rooted in sustainability. By promoting responsible practices with our operators, we strive to create a lasting legacy for future generations.",
  },
  {
    title: "Building a Future of Prosperity",
    image: "/images/hijabi.jpg",
    href: "/why-travelshop/climate#progress",
    body: "We foster job creation and long-term growth by safeguarding the cultures and traditions that make our journeys unforgettable. Sustainable tourism is at the heart of TravelShop Booking's mission.",
  },
];

const tabs = [
  { id: "strategy", label: "Environmental Responsibility Strategy" },
  { id: "partners", label: "Ethical Travel Partners" },
  { id: "tips", label: "Eco-Friendly Travel Tips" },
];

const Sustainability = () => {
  const [active, setActive] = useState(tabs[0].id);

  useEffect(() => {
    const sections = tabs
      .map((t) => document.getElementById(t.id))
      .filter((el): el is HTMLElement => el !== null);

    const observer = new IntersectionObserver(
      (entries) => {
        const visible = entries
          .filter((e) => e.isIntersecting)
          .sort((a, b) => b.intersectionRatio - a.intersectionRatio)[0];
        if (visible) setActive(visible.target.id);
      },
      { rootMargin: "-40% 0px -55% 0px", threshold: [0, 0.25, 0.5, 1] },
    );

    sections.forEach((s) => observer.observe(s));
    return () => observer.disconnect();
  }, []);

  return (
    <main className="tw-font-display tw-bg-white">
      {/* Hero */}
      <section className="tw-relative tw-overflow-hidden">
        <div
          className="tw-absolute tw-inset-0 tw-bg-cover tw-bg-center"
          style={{ backgroundImage: "url('/images/sustainability.webp')" }}
          aria-hidden="true"
        />
        <div
          className="tw-absolute tw-inset-0"
          style={{
            background:
              "linear-gradient(180deg, rgba(20,16,28,0.45) 0%, rgba(20,16,28,0.55) 55%, rgba(20,16,28,0.8) 100%)",
          }}
          aria-hidden="true"
        />
        <div className="tw-relative tw-container tw-mx-auto tw-max-w-[1320px] tw-px-6 md:tw-px-8 lg:tw-px-10 tw-py-24 md:tw-py-32">
          <div className="tw-max-w-[760px]">
            <span className="tw-inline-flex tw-items-center tw-gap-2 tw-rounded-full tw-bg-white/10 tw-border tw-border-solid tw-border-white/20 tw-px-4 tw-py-1.5 tw-text-[13px] tw-font-semibold tw-text-white tw-backdrop-blur">
              Sustainability
            </span>
            <h1 className="tw-mt-5 tw-text-[clamp(32px,5vw,56px)] tw-font-bold tw-tracking-tight tw-leading-[1.05] tw-text-white tw-m-0">
              Eco-friendly travel initiatives
            </h1>
            <p className="tw-mt-5 tw-mb-0 tw-text-[17px] tw-leading-[1.6] tw-text-white/85 tw-max-w-[60ch]">
              Our passion for adventure goes hand in hand with our dedication to
              protecting the planet — because travel is a powerful force for
              good.
            </p>
          </div>
        </div>
      </section>

      {/* Intro */}
      <section className="tw-py-12 md:tw-py-16">
        <div className="tw-container tw-mx-auto tw-max-w-[820px] tw-px-6 md:tw-px-8 lg:tw-px-10 tw-text-center">
          <h2 className="tw-text-[clamp(24px,3vw,34px)] tw-font-bold tw-tracking-tight tw-text-[#14101c] tw-m-0">
            Exploring the world is transformative
          </h2>
          <p className="tw-mt-5 tw-mb-0 tw-text-[15px] tw-leading-[1.7] tw-text-[#5d556c]">
            TravelShop Booking&apos;s passion for adventure goes hand in hand
            with our dedication to protecting the planet. Travel isn&apos;t just
            about discovery — it&apos;s a powerful force for good. Each journey
            offers an opportunity to uplift communities and safeguard nature.
            Through responsible travel, we can create a world where people and
            ecosystems thrive together, shaping a more sustainable and promising
            future for everyone.
          </p>
        </div>
      </section>

      {/* Pledge cards */}
      <section className="tw-pb-12 md:tw-pb-16">
        <div className="tw-container tw-mx-auto tw-max-w-[1320px] tw-px-6 md:tw-px-8 lg:tw-px-10">
          <div className="tw-rounded-3xl tw-bg-[#faf8ff] tw-border tw-border-solid tw-border-[#ebe7f0] tw-p-7 md:tw-p-10">
            <div className="tw-grid tw-grid-cols-1 lg:tw-grid-cols-4 tw-gap-6 lg:tw-gap-7">
              <div className="tw-flex tw-flex-col tw-justify-center">
                <span className="tw-text-[13px] tw-font-semibold tw-uppercase tw-tracking-wider tw-text-[#854ec9]">
                  Our Pledge
                </span>
                <h2 className="tw-mt-2 tw-text-[clamp(20px,2.5vw,26px)] tw-font-bold tw-tracking-tight tw-text-[#14101c] tw-m-0">
                  Our Pledge to Responsible Travel
                </h2>
                <p className="tw-mt-3 tw-mb-0 tw-text-[14px] tw-leading-[1.7] tw-text-[#5d556c]">
                  Sustainability is embedded in every aspect of our work — our
                  values align with the United Nations Sustainable Development
                  Goals.
                </p>
              </div>
              {pledges.map((card) => (
                <div
                  key={card.title}
                  className="tw-flex tw-flex-col tw-overflow-hidden tw-rounded-2xl tw-bg-white tw-border tw-border-solid tw-border-[#ebe7f0] hover:tw-shadow-lg tw-transition-shadow tw-duration-200"
                >
                  <img
                    src={card.image}
                    alt={card.title}
                    loading="lazy"
                    className="tw-h-40 tw-w-full tw-object-cover"
                  />
                  <div className="tw-flex tw-flex-col tw-flex-1 tw-p-5">
                    <h3 className="tw-text-[16px] tw-font-bold tw-text-[#14101c] tw-m-0">
                      {card.title}
                    </h3>
                    <p className="tw-mt-2 tw-mb-0 tw-text-[13px] tw-leading-[1.6] tw-text-[#5d556c]">
                      {card.body}
                    </p>
                    <a
                      href={card.href}
                      className="tw-mt-4 tw-inline-flex tw-items-center tw-gap-1.5 tw-self-start tw-text-[14px] tw-font-semibold tw-text-[#854ec9] tw-no-underline hover:tw-underline"
                    >
                      Explore further details <span aria-hidden="true">→</span>
                    </a>
                  </div>
                </div>
              ))}
            </div>
          </div>
        </div>
      </section>

      {/* Sticky tab nav */}
      <div className="tw-sticky tw-top-0 tw-z-30 tw-bg-white/90 tw-backdrop-blur tw-border-0 tw-border-b tw-border-solid tw-border-[#ebe7f0]">
        <div className="tw-container tw-mx-auto tw-max-w-[1320px] tw-px-4 md:tw-px-8">
          <nav
            className="tw-flex tw-gap-1.5 tw-overflow-x-auto tw-py-3"
            style={{ scrollbarWidth: "none" }}
          >
            {tabs.map((tab) => (
              <a
                key={tab.id}
                href={`#${tab.id}`}
                aria-current={active === tab.id ? "true" : undefined}
                className={`tw-whitespace-nowrap tw-rounded-full tw-px-4 tw-py-2 tw-text-[14px] tw-font-semibold tw-no-underline tw-transition-colors ${
                  active === tab.id
                    ? "tw-bg-[#854ec9] tw-text-white"
                    : "tw-text-[#5d556c] hover:tw-bg-[#faf9fc] hover:tw-text-[#14101c]"
                }`}
              >
                {tab.label}
              </a>
            ))}
          </nav>
        </div>
      </div>

      {/* Strategy */}
      <section id="strategy" className="tw-scroll-mt-20 tw-py-12 md:tw-py-16">
        <div className="tw-container tw-mx-auto tw-max-w-[1320px] tw-px-6 md:tw-px-8 lg:tw-px-10">
          <div className="tw-grid tw-grid-cols-1 lg:tw-grid-cols-2 tw-gap-10 lg:tw-gap-14 tw-items-center">
            <div>
              <span className="tw-text-[13px] tw-font-semibold tw-uppercase tw-tracking-wider tw-text-[#854ec9]">
                Strategy
              </span>
              <h2 className="tw-mt-2 tw-text-[clamp(24px,3vw,34px)] tw-font-bold tw-tracking-tight tw-text-[#14101c] tw-m-0">
                Environmental Responsibility
              </h2>
              <p className="tw-mt-4 tw-text-[15px] tw-leading-[1.7] tw-text-[#5d556c]">
                We understand that meaningful change comes from action, so
                we&apos;ve stepped up to make a difference. The coming years
                will be transformative for our team, our partners, and the way
                we operate. Explore our bold initiatives!
              </p>
              <a
                href="/why-travelshop/climate"
                target="_blank"
                rel="noopener noreferrer"
                className="tw-mt-6 tw-inline-flex tw-items-center tw-gap-2 tw-bg-[#854ec9] hover:tw-bg-[#6a3da4] tw-text-white tw-font-semibold tw-text-[15px] tw-px-6 tw-py-3.5 tw-rounded-full tw-no-underline tw-transition-colors"
              >
                See our commitment <span aria-hidden="true">→</span>
              </a>
            </div>
            <div>
              <img
                src="/images/naturebanner.jpg"
                alt="Nature"
                loading="lazy"
                className="tw-w-full tw-rounded-2xl tw-object-cover tw-shadow-xl tw-shadow-[#14101c]/10"
              />
            </div>
          </div>
        </div>
      </section>

      {/* Partners */}
      <section
        id="partners"
        className="tw-scroll-mt-20 tw-py-12 md:tw-py-16 tw-bg-[#faf9fc]"
      >
        <div className="tw-container tw-mx-auto tw-max-w-[1320px] tw-px-6 md:tw-px-8 lg:tw-px-10">
          <div className="tw-grid tw-grid-cols-1 lg:tw-grid-cols-2 tw-gap-10 lg:tw-gap-14 tw-items-center">
            <div className="tw-order-2 lg:tw-order-1">
              <img
                src="/images/kayak.jpg"
                alt="Kayaking"
                loading="lazy"
                className="tw-w-full tw-rounded-2xl tw-object-cover tw-shadow-xl tw-shadow-[#14101c]/10"
              />
            </div>
            <div className="tw-order-1 lg:tw-order-2">
              <span className="tw-text-[13px] tw-font-semibold tw-uppercase tw-tracking-wider tw-text-[#854ec9]">
                Partners
              </span>
              <h2 className="tw-mt-2 tw-text-[clamp(24px,3vw,34px)] tw-font-bold tw-tracking-tight tw-text-[#14101c] tw-m-0">
                Ethical Adventure Providers
              </h2>
              <p className="tw-mt-4 tw-text-[15px] tw-leading-[1.7] tw-text-[#5d556c]">
                We&apos;re committed to making sure all our suppliers implement
                sustainable practices by 2030. But what defines a responsible
                tour operator? We&apos;ve set clear criteria to help you
                identify and select operators that put sustainability first.
              </p>
              <p className="tw-mt-3 tw-text-[15px] tw-leading-[1.7] tw-text-[#5d556c]">
                Discover how TravelShop Booking brings together travelers,
                agents, and partners with responsible operators through
                Sustainability Cards and an Impact Measurement Tool.
              </p>
              <a
                href="/why-travelshop/actionOperators"
                target="_blank"
                rel="noopener noreferrer"
                className="tw-mt-6 tw-inline-flex tw-items-center tw-gap-2 tw-bg-[#854ec9] hover:tw-bg-[#6a3da4] tw-text-white tw-font-semibold tw-text-[15px] tw-px-6 tw-py-3.5 tw-rounded-full tw-no-underline tw-transition-colors"
              >
                Actions led by operators <span aria-hidden="true">→</span>
              </a>
            </div>
          </div>
        </div>
      </section>

      {/* Tips */}
      <section id="tips" className="tw-scroll-mt-20 tw-py-12 md:tw-py-16">
        <div className="tw-container tw-mx-auto tw-max-w-[1320px] tw-px-6 md:tw-px-8 lg:tw-px-10">
          <div className="tw-grid tw-grid-cols-1 lg:tw-grid-cols-2 tw-gap-10 lg:tw-gap-14 tw-items-center">
            <div>
              <span className="tw-text-[13px] tw-font-semibold tw-uppercase tw-tracking-wider tw-text-[#854ec9]">
                Tips
              </span>
              <h2 className="tw-mt-2 tw-text-[clamp(24px,3vw,34px)] tw-font-bold tw-tracking-tight tw-text-[#14101c] tw-m-0">
                Tips for Minimizing Your Environmental Footprint
              </h2>
              <p className="tw-mt-4 tw-text-[15px] tw-leading-[1.7] tw-text-[#5d556c]">
                Do you ever feel guilty about the environmental impact of your
                travels? Want to explore the world while making a positive
                difference? We&apos;ve put together a list of our top
                sustainability tips and tricks to help make your journey more
                rewarding, enriching, and eco-friendly.
              </p>
              <p className="tw-mt-3 tw-text-[15px] tw-leading-[1.7] tw-text-[#5d556c]">
                From selecting sustainable accommodations to packing
                eco-friendly essentials, these practical tips will guide you in
                reducing your carbon footprint while supporting local
                communities.
              </p>
              <a
                href="/why-travelshop/positiveImpact"
                target="_blank"
                rel="noopener noreferrer"
                className="tw-mt-6 tw-inline-flex tw-items-center tw-gap-2 tw-bg-[#854ec9] hover:tw-bg-[#6a3da4] tw-text-white tw-font-semibold tw-text-[15px] tw-px-6 tw-py-3.5 tw-rounded-full tw-no-underline tw-transition-colors"
              >
                Create a Positive Impact <span aria-hidden="true">→</span>
              </a>
            </div>
            <div>
              <img
                src="/images/play.webp"
                alt="Play"
                loading="lazy"
                className="tw-w-full tw-rounded-2xl tw-object-cover tw-shadow-xl tw-shadow-[#14101c]/10"
              />
            </div>
          </div>
        </div>
      </section>

      <BlogTeasers />

      <TourCategories id="destinations" />

      <Destinations />
    </main>
  );
};

export default Sustainability;
